snippet_css:
:root{
  --bg: #FDFCF8;
  --fg: #2B2B2B;
  --muted: #5F5A52;
  --surface: #FFFFFF;
  --border: #E3DCCB;
  --accent: #B8433C;
  --accent-fg: #FFFFFF;
  --radius: 10px;
  --radius-sm: 6px;
  --shadow: 2px 3px 0 rgba(43,43,43,.14);
  --btn-shadow: 0 3px 0 rgba(43,43,43,.28);
  --art-bg: linear-gradient(160deg,#9FD3E6,#F6C28B 60%,#E07A5F);
  --media-bg: linear-gradient(160deg,#FBE3C5,#E8A87C);
  --cta-bg: #F6EFE0;
  --input-bg: #FFFFFF;
  --ok: #3F7D5A;
  --warn: #B0421F;
  --font-display: 'Caveat','Noto Sans TC',cursive;
  --font-body: 'Lora','Noto Sans TC',serif;
  --font-mono: 'Special Elite',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

